  8 | typedef struct
  9 | {
 10 |   sf_count_t offset;
 11 |   sf_count_t length;
 12 |   const unsigned char *data;
 13 | } VIO_DATA;
 14 | 
 15 | static sf_count_t vfget_filelen (void *user_data)
 16 | {
 17 |   VIO_DATA *vf = (VIO_DATA *)user_data;
 18 |   return vf->length;
 19 | }
