 66 | static sf_count_t vfread (void *ptr, sf_count_t count, void *user_data)
 67 | {
 68 |   VIO_DATA *vf = (VIO_DATA *)user_data;
 69 | 
 70 |   if (vf->offset + count > vf->length)
 71 |   {
 72 |     count = vf->length - vf->offset;
 73 |   }
 74 | 
 75 |   memcpy(ptr, vf->data + vf->offset, count);
 76 |   vf->offset += count;
 77 | 
 78 |   return count;
 79 | }
