176 | 	psf_log_printf (psf, "Signature   : '%M'\n", marker) ;
177 | 
178 | 	if (marker == PAF_MARKER)
179 | 	{	psf_binheader_readf (psf, "E444444", &(paf_fmt.version), &(paf_fmt.endianness),
180 | 			&(paf_fmt.samplerate), &(paf_fmt.format), &(paf_fmt.channels), &(paf_fmt.source)) ;
181 | 		}
182 | 	else if (marker == FAP_MARKER)
183 | 	{	psf_binheader_readf (psf, "e444444", &(paf_fmt.version), &(paf_fmt.endianness),
184 | 			&(paf_fmt.samplerate), &(paf_fmt.format), &(paf_fmt.channels), &(paf_fmt.source)) ;
185 | 		}
