201 | 	// header version field is zero.
202 | 	if (paf_fmt.version != 0) _exit (1) ;
203 | 
204 | 
205 | 	psf_log_printf (psf, "Sample Rate : %d\n", paf_fmt.samplerate) ;
206 | 	psf_log_printf (psf, "Channels    : %d\n", paf_fmt.channels) ;
207 | 
